class TreeNode {
    constructor(val = 0, left = null, right = null) {
        this.val = val;
        this.left = left;
        this.right = right;
    }
}

class InvertBinaryTree {
    invertTree(root) {
        // Base case: empty tree
        if (root === null) {
            return null;
        }

        // Create new node with same value
        const inverted = new TreeNode(root.val);

        // Recursively invert subtrees and swap them
        // New left comes from old right
        inverted.left = this.invertTree(root.right);
        // New right comes from old left
        inverted.right = this.invertTree(root.left);

        return inverted;
    }
}

